void mainImage(out vec4 fragColor, in vec2 fragCoord) {

    vec2 uv = fragCoord / iResolution.xy;

    uv = uv * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y; 

    float angle = iTime * 0.4; // Rotation speed
    float cosAngle = cos(angle);
    float sinAngle = sin(angle);
    mat2 rotation = mat2(cosAngle, -sinAngle, sinAngle, cosAngle);
    uv = rotation * uv; 

    float wave = sin((uv.x + iTime * 0.5) * 10.0) * 0.125; 


    float modWave = sin((uv.x + iTime) * 5.0); // Modulating wave
    float dynamicThickness = 0.08 + 0.06 * sin(iTime * 10.0 + uv.x * 2.0);


    float dist = abs(uv.y - wave);


    float smoothEdge = smoothstep(0.0, dynamicThickness, dynamicThickness - dist + 0.16);


    vec3 color = vec3(smoothEdge);


    fragColor = vec4(color, 1.0);
}
